Angular.ejemplo:
@Component({
  selector: 'app-counter',
  standalone: true,
  template: `<button (click)="inc()">{{ count() }} (x2: {{ doubled() }})</button>`
})
export class CounterComponent {
  count = signal(0);
  doubled = computed(() => this.count() * 2);
  inc() { this.count.update(v => v + 1); }
}

